const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Shanghai and Wuhan
  const shanghai = ee.Geometry.Point([121.47, 31.23]);
  const wuhan = ee.Geometry.Point([114.31, 30.59]);

  // Buffer to ~30km to capture city-scale data
  const shanghaiBuffer = shanghai.buffer(30000);
  const wuhanBuffer = wuhan.buffer(30000);

  // 2. Define date range
  const startDate = '2020-04-20';
  const endDate = '2020-05-12';

  // 3. Load Sentinel-5P TROPOMI NO2 collection
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_NO2')
    .filterDate(startDate, endDate);

  const collectionSize = no2Collection.size().getInfo();
  console.log('TROPOMI NO2 images in period: ' + collectionSize);

  if (collectionSize === 0) {
    console.log('No TROPOMI data available for April 20 - May 12, 2020');
    console.log('C1');
    return;
  }

  // 4. Calculate mean NO2 for Shanghai
  const no2BandShanghai = no2Collection.select('NO2_column_number_density');
  const shanghaiMean = no2BandShanghai.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghaiBuffer,
    scale: 5000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  const shanghaiCount = no2BandShanghai.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghaiBuffer,
    scale: 5000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  // 5. Calculate mean NO2 for Wuhan
  const no2BandWuhan = no2Collection.select('NO2_column_number_density');
  const wuhanMean = no2BandWuhan.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhanBuffer,
    scale: 5000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  const wuhanCount = no2BandWuhan.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhanBuffer,
    scale: 5000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  console.log('Shanghai: Mean=' + (shanghaiMean !== null ? shanghaiMean.toFixed(6) : 'null') + ' Pixels=' + shanghaiCount);
  console.log('Wuhan: Mean=' + (wuhanMean !== null ? wuhanMean.toFixed(6) : 'null') + ' Pixels=' + wuhanCount);

  // 6. Validation & comparison
  if (shanghaiMean === null || wuhanMean === null) {
    console.log('Null values detected in calculations');
    console.log('C3');
    return;
  }

  if (shanghaiCount === 0 || wuhanCount === 0) {
    console.log('No valid pixels found for one or both locations');
    console.log('C2');
    return;
  }

  // 7. Compare means
  if (shanghaiMean > wuhanMean) {
    console.log('Shanghai NO2 (' + shanghaiMean.toFixed(6) + ') > Wuhan NO2 (' + wuhanMean.toFixed(6) + ')');
    console.log('A');
  } else {
    console.log('Shanghai NO2 (' + shanghaiMean.toFixed(6) + ') <= Wuhan NO2 (' + wuhanMean.toFixed(6) + ')');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
